# __setitem__ methods
def setitem_bool(self, row_loc, col_loc, item):
    def _set_item(df, row_loc):  # pragma: no cover
        df = df.copy()
        df.loc[row_loc.squeeze(axis=1), col_loc] = item
        return df

    if self._modin_frame.has_materialized_dtypes and is_scalar(item):
        new_dtypes = self.dtypes.copy()
        if isinstance(col_loc, slice):
            cols_to_set = self.columns[col_loc]
        elif is_list_like(col_loc):
            cols_to_set = col_loc
        else:
            cols_to_set = [col_loc]
        try:
            for col in cols_to_set:
                # Emulating the pandas logic of updating dtypes on a boolean
                # scalar setitem with a zero-length dummy frame in order to
                # avoid computing the actual dtypes of the result.
                dummy = pandas.DataFrame(
                    {0: pandas.Series([], dtype=new_dtypes[col])}
                )
                dummy.loc[pandas.Series([], dtype=bool), 0] = item
                new_dtypes[col] = dummy.dtypes[0]
        except (TypeError, ValueError):
            new_dtypes = None
    else:
        new_dtypes = None

    new_modin_frame = self._modin_frame.broadcast_apply_full_axis(
        axis=1,
        func=_set_item,
        other=row_loc._modin_frame,
        new_index=self._modin_frame.copy_index_cache(),
        new_columns=self._modin_frame.copy_columns_cache(),
        keep_partitioning=False,
        dtypes=new_dtypes,
    )
    return self.__constructor__(new_modin_frame)
